// Regenerates js/stars.js from the Yale Bright Star Catalogue, 5th revised edition
// (Hoffleit & Warren 1991, CDS catalogue V/50), keeping the stars down to V = 6.0 (the
// naked-eye limit). The generated file is committed, so the build never needs the network.
//   node tools/make-stars.mjs [path/to/catalog]     (downloads it from CDS without a path)
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const URL_BSC = 'https://cdsarc.cds.unistra.fr/ftp/V/50/catalog.gz';
const V_LIMIT = 6.0;

let text;
if (process.argv[2]) {
  const raw = fs.readFileSync(process.argv[2]);
  text = (raw[0] === 0x1f && raw[1] === 0x8b ? zlib.gunzipSync(raw) : raw).toString('latin1');
} else {
  const res = await fetch(URL_BSC);
  if (!res.ok) throw new Error(`download failed: ${res.status}`);
  text = zlib.gunzipSync(Buffer.from(await res.arrayBuffer())).toString('latin1');
}

// fixed-width columns (1-based, inclusive) from the catalogue's ReadMe
const col = (line, a, b) => line.slice(a - 1, b).trim();
const stars = [];
for (const line of text.split('\n')) {
  const rah = col(line, 76, 77), vs = col(line, 103, 107);
  if (!rah || !vs) continue;   // a few entries (novae, non-stellar objects) have no position
  const v = Number(vs);
  if (!(v <= V_LIMIT)) continue;
  const ra = (Number(rah) + Number(col(line, 78, 79)) / 60 + Number(col(line, 80, 83)) / 3600) * (Math.PI / 12);
  const decAbs = Number(col(line, 85, 86)) + Number(col(line, 87, 88)) / 60 + Number(col(line, 89, 90)) / 3600;
  const dec = (col(line, 84, 84) === '-' ? -decAbs : decAbs) * (Math.PI / 180);
  const bvs = col(line, 110, 114);
  stars.push({ ra, dec, v, bv: bvs ? Number(bvs) : 0.6 });
}
stars.sort((a, b) => a.v - b.v);   // brightest first

// 6 bytes per star, little endian: RA uint16 (2 pi / 65536), Dec int16 (pi/2 / 32767),
// V uint8 ((V + 2) * 20), B-V int8 (* 50)
const buf = Buffer.alloc(stars.length * 6);
stars.forEach((s, i) => {
  const o = i * 6;
  buf.writeUInt16LE(Math.round((s.ra / (2 * Math.PI)) * 65536) & 0xffff, o);
  buf.writeInt16LE(Math.round((s.dec / (Math.PI / 2)) * 32767), o + 2);
  buf.writeUInt8(Math.max(0, Math.min(255, Math.round((s.v + 2) * 20))), o + 4);
  buf.writeInt8(Math.max(-128, Math.min(127, Math.round(s.bv * 50))), o + 5);
});

const out = `// Generated by tools/make-stars.mjs from the Yale Bright Star Catalogue, 5th revised ed.
// (Hoffleit & Warren 1991, CDS V/50): ${stars.length} stars down to V = ${V_LIMIT}, J2000, brightest first.
// 6 bytes per star, little endian: RA uint16 (2 pi / 65536), Dec int16 (pi/2 / 32767),
// V uint8 ((V + 2) * 20), B-V int8 (* 50). Decoded by decodeStars() in astro.js.
export const STAR_COUNT = ${stars.length};
export const STAR_DATA = '${buf.toString('base64')}';
`;
fs.writeFileSync(path.join(root, 'js/stars.js'), out);
console.log(`wrote js/stars.js: ${stars.length} stars, ${(out.length / 1024).toFixed(0)} KB`);
